/* ===== characters v3: pick a base, then swap eyes, ears, hat, back, and tail =====
   Built in a front-facing frame (+z), turned to face +x inside the toy. Parts that the
   walk cycle swings (arms, wings, cape) sit in toy-frame holders so the swing axes stay right. */
function vin(c){return plastic(c,{roughness:.5,clearcoat:.25,clearcoatRoughness:.4,envMapIntensity:.7})}
function glo(c){return plastic(c,{roughness:.3,clearcoat:.9,clearcoatRoughness:.12,envMapIntensity:.85})}
function latheS(pts,mat,seg){var sp=new T.SplineCurve(pts.map(function(p){return new T.Vector2(p[0],p[1])})).getPoints(64);sp[0].x=Math.max(.0001,sp[0].x);sp[sp.length-1].x=.0001;return M(new T.LatheGeometry(sp,seg||48),mat)}
function holder(parent,lx,ly,lz){var a=new T.Group();a.position.set(lz,ly,-lx);parent.add(a);var c=new T.Group();c.rotation.y=Math.PI/2;a.add(c);return {a:a,c:c}}
function eyeZ(r,lid,iris,spark){var e=new T.Group(),inner=new T.Group();inner.scale.set(1,1,.6);e.add(inner);e.userData.look=true;
 inner.add(new T.Mesh(new T.SphereGeometry(r,28,20),glo("#ffffff")));
 var ir=new T.Mesh(new T.SphereGeometry(r*1.015,28,10,0,Math.PI*2,0,.7),glo(iris||"#2f6fd0"));ir.rotation.x=Math.PI/2;inner.add(ir);
 var pu=new T.Mesh(new T.SphereGeometry(r*1.03,24,8,0,Math.PI*2,0,.36),glo("#0a0f2a"));pu.rotation.x=Math.PI/2;inner.add(pu);
 var wb=new T.MeshBasicMaterial({color:"#ffffff"});
 if(spark){var st=new T.Mesh(STARGEO,wb);st.scale.setScalar(r*.9);st.position.set(-r*.3,r*.32,r*1.0);inner.add(st)}else{var c1=new T.Mesh(new T.SphereGeometry(r*.22,12,8),wb);c1.position.set(-r*.32,r*.4,r*1.0);inner.add(c1)}
 var c2=new T.Mesh(new T.SphereGeometry(r*.11,8,6),wb);c2.position.set(r*.28,-r*.3,r*1.0);inner.add(c2);
 if(lid){var ld=new T.Mesh(new T.SphereGeometry(r*1.06,26,10,0,Math.PI*2,0,.78),vin(lid));ld.rotation.x=.4;inner.add(ld)}
 return noShadow(e)}
function smileZ(w,mat){var cv=new T.QuadraticBezierCurve3(new T.Vector3(-w,0,0),new T.Vector3(0,-w*.9,0),new T.Vector3(w,0,0));return noShadow(M(new T.TubeGeometry(cv,16,w*.18,8,false),mat))}
function blushZ(r,x,y,z,yaw){var m=new T.Mesh(new T.CircleGeometry(r,18),new T.MeshBasicMaterial({color:0xff8fa8,transparent:true,opacity:.5,depthWrite:false}));m.position.set(x,y,z);m.rotation.y=yaw;return m}
