function edApply(rebuild){try{localStorage.setItem(ED.kid?"tvCreate":"tvLevel",JSON.stringify(ED.R))}catch(e){}WORLDS.custom=edEngine(ED.R);if(rebuild!==false)buildWorld("custom");edMarkers();edPanel()}
