/* ===== new world art: Beach, Snow Peak, Toy Room ===== */
function stripeTex(cols,n,vert){var key="st"+cols.join()+n+vert;if(TEX[key])return TEX[key];var c=document.createElement("canvas");c.width=c.height=128;var g=c.getContext("2d");for(var i=0;i<n;i++){g.fillStyle=cols[i%cols.length];if(vert)g.fillRect(i*128/n,0,128/n+1,128);else g.fillRect(0,i*128/n,128,128/n+1)}var t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;TEX[key]=t;return t}
function letterTex(ch,bg){var key="lt"+ch+bg;if(TEX[key])return TEX[key];var c=document.createElement("canvas");c.width=c.height=128;var g=c.getContext("2d");g.fillStyle=bg;g.fillRect(0,0,128,128);g.strokeStyle="rgba(255,255,255,.85)";g.lineWidth=8;g.strokeRect(10,10,108,108);g.fillStyle="#ffffff";g.font="800 76px Rubik, sans-serif";g.textAlign="center";g.textBaseline="middle";g.fillText(ch,64,70);var t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;TEX[key]=t;return t}
function blockMat(ch,bg){return new T.MeshPhysicalMaterial({map:letterTex(ch,bg),roughness:.35,clearcoat:.8})}
/* scenery */
function palm(x,z){var g=new T.Group();g.position.set(x,0,z);var tm=plastic("#b88a5a",{roughness:.8,clearcoat:.05}),rm=plastic("#9a6f45",{roughness:.8}),px=0,py=0;for(var i=0;i<9;i++){var seg=M(new T.CylinderGeometry(.2-i*.008,.24-i*.008,.48,10),tm,px,py+.24,0);seg.rotation.z=-i*.035;g.add(seg);var rg=M(new T.TorusGeometry(.21-i*.008,.035,6,14),rm,px,py+.02,0);rg.rotation.x=Math.PI/2;g.add(rg);px+=Math.sin(i*.035)*.48;py+=.46}
 var top=new T.Group();top.position.set(px,py,0);for(var f=0;f<7;f++){var fr=new T.Group();fr.rotation.y=f/7*Math.PI*2;var lf=M(new T.SphereGeometry(1,16,8),plastic(f%2?"#2fae6a":"#249a5c",{roughness:.6}),1.1,-.25,0);lf.scale.set(1.25,.07,.32);lf.rotation.z=-.35;fr.add(lf);top.add(fr)}
 [[.25,-.25,.1],[-.15,-.3,.22],[.05,-.3,-.25]].forEach(function(c){top.add(M(new T.SphereGeometry(.17,12,10),plastic("#6b4423"),c[0],c[1],c[2]))});g.add(top);return add(g)}
function umbrella(x,z){var g=new T.Group();g.position.set(x,0,z);var pole=new T.Group();pole.rotation.z=.12;g.add(pole);pole.add(M(new T.CylinderGeometry(.04,.04,2.6,8),plastic("#f4f4f4"),0,1.3,0));pole.add(M(new T.ConeGeometry(1.5,.6,16,1,true),new T.MeshPhysicalMaterial({map:stripeTex(["#ff5a4d","#fff6ea"],8,true),roughness:.5,clearcoat:.3,side:T.DoubleSide}),0,2.55,0));pole.add(M(new T.SphereGeometry(.07,8,6),plastic("#ff5a4d"),0,2.88,0));
 g.add(M(new T.BoxGeometry(1.6,.03,.8),new T.MeshPhysicalMaterial({map:stripeTex(["#52b7ff","#ffffff"],6,false),roughness:.7}),.9,.03,.7));return add(g)}
function sandcastle(x,z){var g=new T.Group();g.position.set(x,0,z);var sm=texMat("sand",{bs:.02,r:.9});g.add(M(rbox(1.8,.5,1.2,.1),sm,0,.25,0));[[-.7,-.45],[.7,-.45],[-.7,.45],[.7,.45]].forEach(function(p){g.add(M(new T.CylinderGeometry(.24,.28,.9,12),sm,p[0],.7,p[1]));g.add(M(new T.ConeGeometry(.28,.36,12),sm,p[0],1.33,p[1]))});g.add(M(new T.CylinderGeometry(.36,.4,1.2,14),sm,0,.95,0));for(var i=0;i<6;i++){var a=i/6*Math.PI*2;g.add(M(new T.BoxGeometry(.12,.16,.12),sm,Math.cos(a)*.3,1.62,Math.sin(a)*.3))}g.add(M(new T.CylinderGeometry(.015,.015,.6,6),plastic("#f4f4f4"),0,1.9,0));g.add(M(new T.BoxGeometry(.3,.18,.02),plastic("#ff5a4d"),.15,2.1,0));return add(g)}
function pine(x,z){var g=new T.Group();g.position.set(x,0,z);g.add(M(new T.CylinderGeometry(.16,.22,1,8),plastic("#6b4a5f",{roughness:.8}),0,.5,0));[[1.5,1.6,1.2],[1.2,1.4,2.1],[.9,1.2,2.9],[.55,1,3.6]].forEach(function(c){g.add(M(new T.ConeGeometry(c[0],c[1],10),matte("#1f6a6e",true),0,c[2],0));g.add(M(new T.ConeGeometry(c[0]*.62,c[1]*.42,10),matte("#eef4ff",true),0,c[2]+c[1]*.33,0))});return add(g)}
function snowman(x,z){var g=new T.Group();g.position.set(x,0,z);var sn=plastic("#f4f8ff",{roughness:.7,clearcoat:.1}),ink=plastic("#10163a");g.add(M(new T.SphereGeometry(.62,22,16),sn,0,.55,0));g.add(M(new T.SphereGeometry(.46,22,16),sn,0,1.4,0));g.add(M(new T.SphereGeometry(.33,20,14),sn,0,2.05,0));var ns=M(new T.ConeGeometry(.07,.36,10),plastic("#ff8a3a"),0,2.05,.48);ns.rotation.x=Math.PI/2;g.add(ns);[-.12,.12].forEach(function(e){g.add(M(new T.SphereGeometry(.04,8,6),ink,e,2.15,.3))});[.3,.1,-.1].forEach(function(y){g.add(M(new T.SphereGeometry(.05,8,6),ink,0,1.4+y,.45))});var sc=M(new T.TorusGeometry(.33,.08,8,20),plastic("#ff5a4d"),0,1.78,0);sc.rotation.x=Math.PI/2;g.add(sc);g.add(M(new T.CylinderGeometry(.24,.24,.36,16),plastic("#22337e"),0,2.45,0));g.add(M(new T.CylinderGeometry(.36,.36,.04,16),plastic("#22337e"),0,2.28,0));[1,-1].forEach(function(k){var ar=M(new T.CylinderGeometry(.025,.03,.9,6),plastic("#6b4a5f"),k*.75,1.55,0);ar.rotation.z=k*1.0;g.add(ar)});return add(g)}
function iglooTex(){if(TEX.igloo)return TEX.igloo;var c=document.createElement("canvas");c.width=c.height=256;var g=c.getContext("2d");g.fillStyle="#f4f8ff";g.fillRect(0,0,256,256);g.strokeStyle="#b8cbec";g.lineWidth=4;for(var r=0;r<8;r++){var y=r*32;g.beginPath();g.moveTo(0,y);g.lineTo(256,y);g.stroke();for(var cI=0;cI<8;cI++){var x=cI*32+(r%2?16:0);g.beginPath();g.moveTo(x,y);g.lineTo(x,y+32);g.stroke()}}var t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(3,2);TEX.igloo=t;return t}
function igloo(x,z){var g=new T.Group();g.position.set(x,0,z);var im=new T.MeshPhysicalMaterial({map:iglooTex(),roughness:.6,clearcoat:.2});g.add(at(hemiSphere(2.2,im),0,0,0));var tn=M(new T.SphereGeometry(.95,24,12,0,Math.PI*2,0,Math.PI/2),im,0,0,1.9);tn.scale.z=1.35;g.add(tn);var door=new T.Mesh(new T.CircleGeometry(.5,24,0,Math.PI),new T.MeshBasicMaterial({color:"#0a0f2a"}));door.position.set(0,0,3.18);g.add(door);return add(g)}
function roomLamp(x,z){var g=new T.Group();g.position.set(x,0,z);g.add(M(new T.CylinderGeometry(.45,.5,.1,20),metal("#c9a86a"),0,.05,0));g.add(M(new T.CylinderGeometry(.05,.05,3.2,10),metal("#c9a86a"),0,1.65,0));g.add(M(new T.CylinderGeometry(.5,.85,.8,20,1,true),new T.MeshPhysicalMaterial({color:"#ffe2a8",emissive:"#ffb04a",emissiveIntensity:.6,side:T.DoubleSide,roughness:.6}),0,3.4,0));g.add(M(new T.SphereGeometry(.18,12,10),glowMat("#fff1c0",2.2),0,3.25,0));var gl=glowSprite("rgba(255,200,120,0.6)",4);gl.position.set(0,3.2,.2);g.add(gl);var pl=new T.PointLight(0xffc27a,1.6,9,2);pl.position.set(0,3.1,.6);g.add(pl);return add(g)}
function toyBlocks(x,z){var g=new T.Group();g.position.set(x,0,z);[["A","#ff5a4d",-.5,.45,0,.1],["B","#52b7ff",.5,.45,.1,-.15],["C","#ffd24d",0,1.35,0,.2]].forEach(function(b){var m=M(new T.BoxGeometry(.9,.9,.9),blockMat(b[0],b[1]),b[2],b[3],b[4]);m.rotation.y=b[5];g.add(m)});return add(g)}
